import { read } from 'claude-code'
import type { Register, TurnStepChunk } from 'claude-code'

import { overloadWaitMs } from './backoff'
import { applyOptions, mergeFiles, validate } from './config'
import { backgroundOf, isPersonPrompt, Keeper } from './keeper'

const TOOL = 'request_compact'
const TOOL_NAME = 'mcp__keep-going__request_compact'
const MAX_LOG_LINES = 2000

const WRAP_UP = /Approaching your [\w-]+(?: usage)? limit|\[Usage limit approaching\. Checkpoint now/

const HELP = [
  '/keep-going [status]       what is pending in this session',
  '/keep-going continue       send the pending continue now',
  '/keep-going cancel         drop the pending continue or compaction',
  '/keep-going compact [what] compact once idle, keeping what you name',
  '/keep-going pause|resume   stop or restart acting in this session',
].join('\n')

function parsed(text: string): unknown {
  try {
    return JSON.parse(text)
  } catch {
    return null
  }
}

function textOf(content: unknown): string {
  if (typeof content === 'string') return content
  if (!Array.isArray(content)) return ''
  return content
    .map((block: { type?: unknown; text?: unknown }) => (block?.type === 'text' && typeof block.text === 'string' ? block.text : ''))
    .join('\n')
}

export const register: Register = (on, options) => {
  const lines: string[] = []
  let logPath = ''
  let isLogDirty = false
  let uiLog: ((text: string, toTranscript: boolean) => void) | null = null
  let flushLog: () => Promise<void> = async () => {}
  let badgePath = ''
  let statuslinePath = ''
  let isPrintRun = false
  const events: string[] = []

  const dump = (event: string, e: unknown) => {
    if (!keeper.config.debug.dumpEvents) return
    events.push(JSON.stringify({ at: new Date().toISOString(), event, e }).slice(0, 8000))
    isLogDirty = true
  }

  const write = (level: string, line: string, toTranscript: boolean) => {
    const d = new Date()
    const stamp = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')} `
      + `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}:${String(d.getSeconds()).padStart(2, '0')}`
    lines.push(`[${stamp}] [${level}] ${line}`)
    if (lines.length > MAX_LOG_LINES) lines.splice(0, lines.length - MAX_LOG_LINES)
    isLogDirty = true
    uiLog?.(line, toTranscript)
  }

  const keeper = new Keeper({
    info: (line) => write('INFO', line, false),
    warn: (line) => write('WARN', line, false),
    notice: (line) => write('INFO', line, true),
  })

  on('session.start', async ($, e, next) => {
    const CORE = { plugin: 'keep-going', key: 'core' } as const
    const VIEW = { plugin: 'keep-going', key: 'view' } as const
    uiLog = (text, toTranscript) => $.ui.log(text, { to: toTranscript ? 'transcript' : 'debug' })
    flushLog = async () => {
      if (!isLogDirty || logPath === '') return
      isLogDirty = false
      try {
        await $.fs.write(logPath, `${lines.join('\n')}\n`)
        if (events.length > 0) await $.fs.write(logPath.replace(/\.log$/, '.events.jsonl'), `${events.join('\n')}\n`)
      } catch {
        isLogDirty = true
      }
    }
    keeper.io = {
      now: () => $.clock.now(),
      saveState: async (core, view) => {
        await $.state.set(CORE, core)
        if (view !== null) await $.state.set(VIEW, view)
      },
      loadCore: async () => (await $.state.get(CORE)).value,
      status: (text) => $.ui.status(text),
      writeBadge: (badge) => $.fs.write(badgePath, badge === '' ? '' : `${badge}\n`),
      storeGet: (key) => $.store.get(key),
      storeSet: (key, value) => $.store.set(key, value),
      storeKeys: () => $.store.keys(),
      storeDelete: (key) => $.store.delete(key),
      rateLimits: async () => (await $.session.usage()).rateLimits,
      context: async () => {
        const usage = await $.session.usage()
        return {
          percent: usage.context.percent ?? null,
          tokens: usage.context.tokens ?? null,
          isSubscription: usage.rateLimits.length > 0,
        }
      },
      model: () => $.session.model(),
      lastAssistantText: async () => {
        const last = (await $.session.messages()).at(-1)
        return last?.role === 'assistant' ? last.text : ''
      },
      cacheExpiresAt: async () => {
        const saved = parsed(await $.fs.read(statuslinePath).catch(() => '')) as
          | { prompt_cache?: { expires_at?: unknown; warm?: unknown } }
          | null
        const cache = saved?.prompt_cache
        if (cache === undefined) return null
        return {
          expiresAt: typeof cache.expires_at === 'number' ? cache.expires_at * 1000 : null,
          isWarm: cache.warm !== false,
        }
      },
      busyAgents: async () => (await $.agent.list())
        .filter((agent) => agent.status === 'pending' || agent.status === 'running').length,
      submit: async (text) => {
        await $.prompt.submit({ text, asUser: true })
      },
      compact: async (focus) => {
        const result = await $.session.compact(focus ? { instructions: focus } : {})
        return result && 'skip' in result && typeof result.skip === 'string' ? result.skip : null
      },
      isReachable: (url, timeoutMs) => Promise.race([
        $.http.fetch(url, { method: 'HEAD' }).then(() => true, () => false),
        $.clock.sleep(timeoutMs).then(() => false, () => false),
      ]),
      after: (ms, fn) => {
        $.clock.after(ms, fn)
      },
    }
    const home = (await $.env.get('HOME')) ?? ''
    const configHome = (await $.env.get('XDG_CONFIG_HOME')) || `${home}/.config`
    const configDirs = ((await $.env.get('XDG_CONFIG_DIRS')) || '/etc/xdg').split(':').filter(Boolean)
    const stateHome = (await $.env.get('XDG_STATE_HOME')) || `${home}/.local/state`
    const runtimeDir = (await $.env.get('XDG_RUNTIME_DIR')) || '/tmp'
    isPrintRun = !e.isInteractive && e.surface === null
    dump('session.start', e)

    const files = []
    for (const path of [...[...configDirs].reverse().map((dir) => `${dir}/claude-keep-going/config.json`), `${configHome}/claude-keep-going/config.json`]) {
      files.push(parsed(await $.fs.read(path).catch(() => '')))
    }
    keeper.config = validate(applyOptions(mergeFiles(files), options))

    const sessionId = await $.session.id()
    const day = new Date().toISOString().slice(0, 10)
    logPath = `${stateHome}/claude-keep-going/logs/mod-${day}-${sessionId.slice(0, 8)}.log`
    badgePath = `${runtimeDir}/claude-keep-going/badge/${sessionId}`
    statuslinePath = `${runtimeDir}/claude-keep-going/statusline/${sessionId}.json`
    await keeper.restore(sessionId)

    try {
      await $.command.register({
        name: 'keep-going',
        description: 'Show or act on what keep-going has pending: continue, cancel, compact, pause',
        argumentHint: '[status|continue|cancel|compact [focus]|pause|resume]',
        immediate: true,
      })
    } catch (error) {
      write('WARN', `could not register /keep-going: ${String(error)}`, false)
    }

    const c = keeper.config.compact
    if (c.enabled && c.trigger !== 'policy') {
      try {
        await $.tool.register({
          name: TOOL,
          description:
            'Ask for this conversation to be compacted once it has been idle a while, before the prompt cache '
            + 'expires. Call it when you finish a large piece of work and what comes next does not need the '
            + 'details of it. Nothing happens while work is still running. `focus` names what the summary should keep.',
          inputSchema: {
            type: 'object',
            properties: { focus: { type: 'string', description: 'What the summary should keep or stress' } },
          },
        })
      } catch (error) {
        write('WARN', `could not register the ${TOOL} tool: ${String(error)}`, false)
      }
    }

    $.clock.every(keeper.config.tickSeconds * 1000, () => {
      void keeper.tick().then(() => flushLog())
    })
    void keeper.sweepStore().catch(() => {})
    write('INFO', `watching session ${sessionId.slice(0, 8)} (${e.isInteractive ? 'interactive' : 'headless'})`, false)
    await keeper.save()
    return next(e)
  })

  on('session.end', async ($, e, next) => {
    await flushLog()
    if (badgePath !== '') await $.fs.write(badgePath, '').catch(() => {})
    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    await keeper.onTurnStart()
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId === undefined) await keeper.onTurnComplete(e.reason, e.answer)
    return next(e)
  })

  on('classic.StopFailure', async ($, e, next) => {
    await keeper.onStopFailure(e.error, e.last_assistant_message ?? e.error_details ?? '')
    return next(e)
  })

  on('classic.Stop', async ($, e, next) => {
    keeper.onStop(backgroundOf(e.background_tasks), e.session_crons?.length ?? 0)
    return next(e)
  })

  on('classic.Notification', async ($, e, next) => {
    keeper.onNotification(await $.clock.now(), e.notification_type)
    await keeper.save()
    return next(e)
  })

  on('classic.PostModelSwitch', async ($, e, next) => {
    keeper.core.cacheTtlMs = e.cache_ttl === '1h' ? 3600_000 : 300_000
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    const model = keeper.stepModel(e.model, Date.now())
    const sent = model === null ? e : { ...e, model }
    const isRetried = isPrintRun && keeper.config.print.enabled && e.agentId === undefined
    const deadline = Date.now() + keeper.config.print.maxWaitHours * 3600_000

    // A print run ends with its one result, so nothing could continue it
    // afterwards: a request that failed before any of its answer arrived is
    // sent again here, after the wait a session would have done.
    for (let attempt = 0; ; attempt++) {
      const stream = next(sent)
      let chunks = 0
      const held: TurnStepChunk[] = []
      let step = await stream.next()
      while (step.done !== true) {
        const chunk = step.value
        if (isRetried && chunks === 0 && chunk.kind === 'engine') {
          held.push(chunk)
        } else {
          chunks += 1
          for (const before of held.splice(0)) yield before
          yield chunk
        }
        step = await stream.next()
      }
      const result = step.value
      dump('turn.step', { chunks, held: held.length, isRetried, result })
      if (result.usage !== null) keeper.learnModel(result.usage.model)
      const isFailed = result.usage === null && result.stopReason === null
      if (isFailed && model !== null) keeper.onFallbackFailed()
      if (!isFailed || !isRetried || chunks > 0 || attempt >= keeper.config.maxRetries) {
        for (const before of held) yield before
        return result
      }

      const { rateLimits } = await $.session.usage()
      const reset = rateLimits
        .filter((w) => w.percentUsed >= 100 && w.resetsAt !== undefined)
        .map((w) => Date.parse(w.resetsAt ?? ''))
        .filter((t) => Number.isFinite(t))
      const waitMs = reset.length > 0
        ? Math.max(...reset) - Date.now() + keeper.config.marginSeconds * 1000
        : overloadWaitMs(attempt, keeper.config.overload, Math.random)
      if (Date.now() + waitMs > deadline) return result
      write('INFO', `print run: request failed, sending it again in ${Math.round(waitMs / 1000)}s`, false)
      await flushLog()
      for (let left = Math.max(0, waitMs); left > 0; left -= 590_000) {
        const seconds = Math.ceil(Math.min(left, 590_000) / 1000)
        await $.process.run(['sleep', String(seconds)], { timeoutMs: (seconds + 10) * 1000 })
      }
    }
  })

  on('session.measure', async ($, e, next) => {
    if (e.changed.includes('rateLimits')) await keeper.onMeasure()
    return next(e)
  })

  on('prompt.submit', async ($, e, next) => {
    dump('prompt.submit', { origin: e.origin, text: e.text.slice(0, 300) })
    if (isPersonPrompt(e.origin.kind)) await keeper.onPersonPrompt()
    else keeper.onDelivered(e.origin.kind)
    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    const tool = String(e.tool)
    if (tool !== 'ScheduleWakeup' && tool !== 'CronCreate' && tool !== 'CronDelete' && tool !== 'Workflow') return next(e)
    const called = await next(e)
    const result = 'result' in called && typeof called.result === 'object' && called.result !== null
      ? (called.result as Record<string, unknown>)
      : null
    if (!('deny' in called && called.deny !== undefined) && called.isError !== true) {
      keeper.onToolCall(await $.clock.now(), tool, e as unknown as Record<string, unknown>, result)
      dump('tool.call', { tool, result })
    }
    return called
  })

  on('command.run', { command: 'rate-limit-options' }, async ($, e, next) => {
    const now = await $.clock.now()
    dump('command.run', { command: e.command, origin: e.origin, lastEditAt: keeper.core.activity.lastEditAt, now })
    if (keeper.config.native.rateLimitMenu === 'show' || now - keeper.core.activity.lastEditAt < 10_000) return next(e)
    const { rateLimits } = await $.session.usage()
    const isLimited = keeper.core.usage !== null || rateLimits.some((w) => w.percentUsed >= 100)
    if (!isLimited) return next(e)
    // Claude Code opens this menu itself when it cannot arm its own
    // auto-continue. Its default may be a paid option; answering it here is
    // what "Stop and wait for limit to reset" does, and the wait is ours.
    write('INFO', 'answered the usage-limit menu Claude Code opened: waiting for the reset', true)
    return {}
  })

  on('prompt.edit', async ($, e, next) => {
    keeper.onEdit(await $.clock.now())
    return next(e)
  })

  on('ui.render', { component: 'InfoNotice' }, async ($, e, next) => {
    keeper.onNotice(await $.clock.now(), e.props.text)
    return next(e)
  })

  on('session.append', async ($, e, next) => {
    if (e.agentId === undefined && e.door !== 'response' && e.door !== 'tool-result' && e.door !== 'prompt') {
      const text = textOf((e.message as { content?: unknown }).content)
      const now = await $.clock.now()
      if (WRAP_UP.test(text)) keeper.onWrapUpNotice(now)
      if (keeper.onNotice(now, text) || WRAP_UP.test(text)) dump('session.append', { door: e.door, message: e.message })
    }
    return next(e)
  })

  on('tool.call', { tool: TOOL_NAME }, async ($, e) => {
    const focus = typeof e.focus === 'string' ? e.focus : ''
    return { result: await keeper.requestCompact(focus) }
  })

  on('command.run', { command: 'keep-going' }, async ($, e) => {
    const [verb = 'status', ...rest] = e.args.trim().split(/\s+/).filter(Boolean)
    switch (verb) {
      case 'status': {
        const view = (await $.state.get({ plugin: 'keep-going', key: 'view' } as const)).value
        const pending = view?.line ?? 'nothing pending'
        return { text: `${pending}${view?.detail ? `\n${view.detail}` : ''}\n\n${HELP}` }
      }
      case 'continue':
        return { text: await keeper.continueNow() }
      case 'cancel':
        return { text: await keeper.cancel() }
      case 'compact':
        return { text: await keeper.requestCompact(rest.join(' ')) }
      case 'pause':
        keeper.core.isPaused = true
        await keeper.save()
        return { text: 'keep-going is paused for this session.' }
      case 'resume':
        keeper.core.isPaused = false
        await keeper.save()
        return { text: 'keep-going is watching this session again.' }
      case 'debug':
        return { text: JSON.stringify({ core: keeper.core, config: keeper.config }, null, 2) }
      case 'log':
        return { text: lines.slice(-20).join('\n') || 'Nothing logged yet.' }
      default:
        return { text: HELP }
    }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (!keeper.config.ui.band || (e.surface !== 'terminal' && e.surface !== 'desktop')) return next(e)
    const view = await read($, { plugin: 'keep-going', key: 'view' } as const)
    if (view === null || view === undefined || view.actions.length === 0 || view.line === null) return next(e)

    const { Box, Text, Button } = $.ui.resolve(e)
    const act = (what: 'continue' | 'cancel' | 'compact' | 'skip') => async () => {
      if (what === 'continue') await keeper.continueNow()
      else if (what === 'compact') {
        keeper.core.compact.scheduledFor = 0
        keeper.core.compact.handledIdleSince = keeper.core.activity.idleSince
        await keeper.compactNow(keeper.core.compact.request?.focus ?? keeper.config.compact.focus, 'from the band')
        keeper.core.compact.request = null
        await keeper.save()
      } else await keeper.cancel()
    }
    const labels = { continue: 'Continue now', cancel: 'Cancel', compact: 'Compact now', skip: 'Skip' } as const

    return (
      <Box flexDirection="row" columnGap={1}>
        <Text dimColor>keep-going: {view.line}</Text>
        {view.actions.map((what) => (
          <Button key={what} label={labels[what]} plain onPress={act(what)} />
        ))}
      </Box>
    )
  })
}

files.hooks/backoff.ts:
import type { Config } from './config'

/**
 * A 529 is global capacity, so every client that waits the same fixed
 * schedule comes back in the same overload window. Full jitter spreads them
 * over the whole interval; the floor keeps a retry from firing at once.
 */
const FULL_JITTER_FLOOR_MS = 5_000

export function overloadWaitMs(attempt: number, overload: Config['overload'], random: () => number): number {
  const seconds = overload.backoffSeconds[attempt] ?? overload.steadyStateSeconds
  const base = seconds * 1000
  if (overload.jitterMode === 'full') {
    return Math.max(Math.min(FULL_JITTER_FLOOR_MS, base), Math.round(random() * base))
  }
  if (overload.jitterPct === 0) return base
  const factor = 1 + (random() * 2 - 1) * (overload.jitterPct / 100)
  return Math.max(0, Math.round(base * factor))
}

/**
 * An overload retry more than this long after the last one starts a new
 * incident with a fresh budget: otherwise one bad night's attempts count
 * against an unrelated outage days later.
 */
export const INCIDENT_GAP_MS = 15 * 60_000

files.hooks/config.ts:
export type CompactTrigger = 'request' | 'policy' | 'both'

export type Config = {
  enabled: boolean
  maxRetries: number
  marginSeconds: number
  fallbackWaitHours: number
  tickSeconds: number
  retryMessage: string
  /** Extra regexes, case-insensitive, that mark an error message as a usage limit. */
  customPatterns: string[]
  overload: {
    enabled: boolean
    backoffSeconds: number[]
    steadyStateSeconds: number
    jitterPct: number
    jitterMode: 'full' | 'proportional'
    maxTotalWaitMinutes: number
    retryMessage: string
  }
  safeguard: BoundedRetry
  streamInterrupted: BoundedRetry
  nearLimitWrapUp: { enabled: boolean; maxRetries: number; retryMessage: string }
  compact: {
    enabled: boolean
    trigger: CompactTrigger
    window: { start: string; end: string } | null
    awayMinutes: number | null
    minContextPercent: number
    minContextTokens: number | null
    settle: { mode: 'before-expiry' | 'fixed'; marginSeconds: number; minutes: number }
    cacheTtlMinutes: number | null
    focus: string
    matchLastMessage: boolean
    minIntervalMinutes: number
    waitForAgents: boolean
  }
  native: { usageLimit: 'defer' | 'ignore'; graceSeconds: number; rateLimitMenu: 'skip' | 'show' }
  print: { enabled: boolean; maxWaitHours: number }
  debug: { dumpEvents: boolean }
  networkCheck: { enabled: boolean; url: string; maxWaitMinutes: number }
  modelFallback: { enabled: boolean; map: Record<string, string>; switchBack: boolean }
  ui: { statusLine: 'active' | 'always' | 'off'; band: boolean }
}

export type BoundedRetry = {
  enabled: boolean
  maxRetries: number
  retryDelaySeconds: number
  retryMessage: string
}

export const DEFAULTS: Config = {
  enabled: true,
  maxRetries: 5,
  marginSeconds: 60,
  fallbackWaitHours: 5,
  tickSeconds: 5,
  retryMessage: 'Continue where you left off. The previous attempt was rate limited.',
  customPatterns: [],
  overload: {
    enabled: true,
    backoffSeconds: [30, 60, 120, 240, 300],
    steadyStateSeconds: 300,
    jitterPct: 15,
    jitterMode: 'full',
    maxTotalWaitMinutes: 120,
    retryMessage: 'Continue where you left off.',
  },
  safeguard: { enabled: true, maxRetries: 3, retryDelaySeconds: 8, retryMessage: 'continue' },
  streamInterrupted: { enabled: true, maxRetries: 2, retryDelaySeconds: 5, retryMessage: 'continue' },
  nearLimitWrapUp: { enabled: true, maxRetries: 3, retryMessage: 'continue' },
  compact: {
    enabled: false,
    trigger: 'request',
    window: null,
    awayMinutes: null,
    minContextPercent: 40,
    minContextTokens: null,
    settle: { mode: 'before-expiry', marginSeconds: 300, minutes: 4 },
    cacheTtlMinutes: null,
    focus: '',
    matchLastMessage: false,
    minIntervalMinutes: 30,
    waitForAgents: true,
  },
  native: { usageLimit: 'defer', graceSeconds: 180, rateLimitMenu: 'skip' },
  print: { enabled: true, maxWaitHours: 6 },
  debug: { dumpEvents: false },
  networkCheck: { enabled: true, url: 'https://api.anthropic.com/', maxWaitMinutes: 10 },
  modelFallback: { enabled: false, map: { Opus: 'sonnet' }, switchBack: true },
  ui: { statusLine: 'active', band: true },
}

type Raw = Record<string, unknown>

const isObject = (v: unknown): v is Raw => typeof v === 'object' && v !== null && !Array.isArray(v)

const num = (v: unknown, min: number, fallback: number) =>
  typeof v === 'number' && Number.isFinite(v) && v >= min ? v : fallback

const bool = (v: unknown, fallback: boolean) => (typeof v === 'boolean' ? v : fallback)

const text = (v: unknown, fallback: string) => (typeof v === 'string' && v !== '' ? v : fallback)

function oneOf<T extends string>(v: unknown, values: readonly T[], fallback: T): T {
  return typeof v === 'string' && (values as readonly string[]).includes(v) ? (v as T) : fallback
}

const nullableNum = (v: unknown, min: number) =>
  typeof v === 'number' && Number.isFinite(v) && v >= min ? v : null

const block = (v: unknown): Raw => (isObject(v) ? v : {})

const CLOCK = /^([01]?\d|2[0-3]):([0-5]\d)$/

function boundedRetry(raw: unknown, d: BoundedRetry): BoundedRetry {
  const b = block(raw)
  return {
    enabled: bool(b.enabled, d.enabled),
    maxRetries: num(b.maxRetries, 1, d.maxRetries),
    retryDelaySeconds: num(b.retryDelaySeconds, 1, d.retryDelaySeconds),
    retryMessage: text(b.retryMessage, d.retryMessage),
  }
}

export function validate(raw: unknown): Config {
  const r = block(raw)
  const d = DEFAULTS

  const o = block(r.overload)
  const backoff = Array.isArray(o.backoffSeconds)
    ? o.backoffSeconds.filter((n): n is number => typeof n === 'number' && Number.isFinite(n) && n > 0)
    : []

  const c = block(r.compact)
  const settle = block(c.settle)
  const window = isObject(c.window) && CLOCK.test(String(c.window.start)) && CLOCK.test(String(c.window.end))
    ? { start: String(c.window.start), end: String(c.window.end) }
    : null

  const nw = block(r.native)
  const nc = block(r.networkCheck)
  const mf = block(r.modelFallback)
  const map = isObject(mf.map) ? mf.map : d.modelFallback.map
  const ui = block(r.ui)

  return {
    enabled: bool(r.enabled, d.enabled),
    maxRetries: num(r.maxRetries, 1, d.maxRetries),
    marginSeconds: num(r.marginSeconds, 0, d.marginSeconds),
    fallbackWaitHours: num(r.fallbackWaitHours, 0.1, d.fallbackWaitHours),
    tickSeconds: num(r.tickSeconds ?? r.pollIntervalSeconds, 1, d.tickSeconds),
    retryMessage: text(r.retryMessage, d.retryMessage),
    customPatterns: Array.isArray(r.customPatterns)
      ? r.customPatterns.filter((p): p is string => {
          if (typeof p !== 'string' || p === '') return false
          try {
            new RegExp(p, 'i')
            return true
          } catch {
            return false
          }
        })
      : [],
    overload: {
      enabled: bool(o.enabled, d.overload.enabled),
      backoffSeconds: backoff.length > 0 ? backoff : [...d.overload.backoffSeconds],
      steadyStateSeconds: num(o.steadyStateSeconds, 1, d.overload.steadyStateSeconds),
      jitterPct: Math.min(100, num(o.jitterPct, 0, d.overload.jitterPct)),
      jitterMode: oneOf(o.jitterMode, ['full', 'proportional'], d.overload.jitterMode),
      maxTotalWaitMinutes: num(o.maxTotalWaitMinutes, 0.1, d.overload.maxTotalWaitMinutes),
      retryMessage: text(o.retryMessage, d.overload.retryMessage),
    },
    safeguard: boundedRetry(r.safeguard, d.safeguard),
    streamInterrupted: boundedRetry(r.streamInterrupted, d.streamInterrupted),
    nearLimitWrapUp: {
      enabled: bool(block(r.nearLimitWrapUp).enabled, d.nearLimitWrapUp.enabled),
      maxRetries: num(block(r.nearLimitWrapUp).maxRetries, 1, d.nearLimitWrapUp.maxRetries),
      retryMessage: text(block(r.nearLimitWrapUp).retryMessage, d.nearLimitWrapUp.retryMessage),
    },
    compact: {
      enabled: bool(c.enabled, d.compact.enabled),
      trigger: oneOf(c.trigger, ['request', 'policy', 'both'], d.compact.trigger),
      window,
      awayMinutes: nullableNum(c.awayMinutes, 0),
      minContextPercent: Math.min(100, num(c.minContextPercent, 0, d.compact.minContextPercent)),
      minContextTokens: nullableNum(c.minContextTokens, 0),
      settle: {
        mode: oneOf(settle.mode, ['before-expiry', 'fixed'], d.compact.settle.mode),
        marginSeconds: num(settle.marginSeconds, 0, d.compact.settle.marginSeconds),
        minutes: num(settle.minutes, 0, d.compact.settle.minutes),
      },
      cacheTtlMinutes: nullableNum(c.cacheTtlMinutes, 1),
      focus: typeof c.focus === 'string' ? c.focus : d.compact.focus,
      matchLastMessage: bool(c.matchLastMessage, d.compact.matchLastMessage),
      minIntervalMinutes: num(c.minIntervalMinutes, 0, d.compact.minIntervalMinutes),
      waitForAgents: bool(c.waitForAgents, d.compact.waitForAgents),
    },
    native: {
      usageLimit: oneOf(nw.usageLimit, ['defer', 'ignore'], d.native.usageLimit),
      graceSeconds: num(nw.graceSeconds, 0, d.native.graceSeconds),
      rateLimitMenu: oneOf(nw.rateLimitMenu, ['skip', 'show'], d.native.rateLimitMenu),
    },
    print: {
      enabled: bool(block(r.print).enabled, d.print.enabled),
      maxWaitHours: num(block(r.print).maxWaitHours, 0, d.print.maxWaitHours),
    },
    debug: { dumpEvents: bool(block(r.debug).dumpEvents, d.debug.dumpEvents) },
    networkCheck: {
      enabled: bool(nc.enabled, d.networkCheck.enabled),
      url: typeof nc.url === 'string' && /^https?:\/\//.test(nc.url) ? nc.url : d.networkCheck.url,
      maxWaitMinutes: num(nc.maxWaitMinutes, 0, d.networkCheck.maxWaitMinutes),
    },
    modelFallback: {
      enabled: bool(mf.enabled, d.modelFallback.enabled),
      switchBack: bool(mf.switchBack, d.modelFallback.switchBack),
      map: Object.fromEntries(
        Object.entries(map).filter(
          (entry): entry is [string, string] =>
            entry[0] !== '' && typeof entry[1] === 'string' && /^[\w.:[\]-]+$/.test(entry[1]),
        ),
      ),
    },
    ui: {
      statusLine: oneOf(ui.statusLine, ['active', 'always', 'off'], d.ui.statusLine),
      band: bool(ui.band, d.ui.band),
    },
  }
}

/**
 * Two config files, merged one level deep with the user's on top: the
 * system one (`$XDG_CONFIG_DIRS`, `/etc/xdg` by default) and the user's
 * (`$XDG_CONFIG_HOME`, `~/.config` by default). The paths are the ones the
 * claude-keep-going CLI reads, so an existing config keeps working.
 */
export function mergeFiles(files: readonly unknown[]): Raw {
  const merged: Raw = {}
  for (const file of files) {
    if (!isObject(file)) continue
    for (const [key, value] of Object.entries(file)) {
      merged[key] = isObject(value) && isObject(merged[key])
        ? { ...(merged[key] as Raw), ...value }
        : value
    }
  }
  return merged
}

/**
 * The `/config` rows the manifest declares, laid over the file. `config`
 * leaves the file's value alone.
 */
export function applyOptions(raw: Raw, options: Readonly<Record<string, unknown>>): Raw {
  const out: Raw = { ...raw }
  const compact = options.compact
  if (compact === 'off') out.compact = { ...block(out.compact), enabled: false }
  else if (compact === 'request' || compact === 'policy' || compact === 'both') {
    out.compact = { ...block(out.compact), enabled: true, trigger: compact }
  }
  const fallback = options.modelFallback
  if (fallback === 'on' || fallback === 'off') {
    out.modelFallback = { ...block(out.modelFallback), enabled: fallback === 'on' }
  }
  const band = options.band
  if (band === 'on' || band === 'off') out.ui = { ...block(out.ui), band: band === 'on' }
  return out
}

